"""A picture or a video as a deck's layer (native/vj_layer.py): its transparency kept, none, or keyed out (a colour,
the dark); where it sits (fit, fill, stretch, tile, scale, place, turn, flip); a video file's alpha found and read
(WebM VP9, ProRes 4444 - made here with ffmpeg, when it is on the PATH); deck C over the mix through it; and a
shader's channel reading a picture of its own. Run with python tests/test_layer.py  (or pytest)."""
# AI: below section was generated by an AI
import os
import shutil
import subprocess
import sys
import tempfile

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.dirname(HERE))

import numpy as np                                    # noqa: E402

from native import video, vj_layer                   # noqa: E402


def _disc(n=40):
    """An RGBA picture: an opaque red disc on a clear (white) ground."""
    yy, xx = np.mgrid[0:n, 0:n]
    inside = ((xx - n / 2 + 0.5) ** 2 + (yy - n / 2 + 0.5) ** 2) < (n * 0.35) ** 2
    img = np.ones((n, n, 4), np.float32)
    img[..., 3] = inside
    img[inside, 1:3] = 0.0
    return img


def test_its_own_alpha_and_none():
    """Its own transparency: clear round the disc, the colour black there (premultiplied); none: all shown, the clear
    white as on black."""
    rgb, a = vj_layer.prepare(_disc(), 40, 40, {"pic_drift": 0.0})
    assert a[20, 20] > 0.99 and a[1, 1] < 0.01 and rgb[1, 1].max() < 0.01 and rgb[20, 20, 0] > 0.99
    rgb, a = vj_layer.prepare(_disc(), 40, 40, {"pic_key": "none", "pic_drift": 0.0})
    assert a.min() > 0.99 and rgb[1, 1].max() < 0.01


def test_keyed_out():
    """A colour keyed out (a green screen) and the dark keyed out, with a soft edge between."""
    img = np.zeros((20, 20, 3), np.float32)
    img[:, :10] = (0.0, 0.8, 0.2)                       # green on the left, magenta on the right
    img[:, 10:] = (0.9, 0.2, 0.8)
    _, a = vj_layer.key(img, {"pic_key": "colour", "pic_key_col": [0.0, 0.8, 0.2], "pic_tol": 0.2, "pic_soft": 0.1})
    assert a[5, 2] < 0.01 and a[5, 15] > 0.99
    dark = np.linspace(0, 1, 20, dtype=np.float32)[None, :, None].repeat(4, 0).repeat(3, 2)
    _, a = vj_layer.key(dark, {"pic_key": "dark", "pic_tol": 0.3, "pic_soft": 0.2})
    assert a[0, 0] == 0.0 and a[0, -1] == 1.0 and 0.0 < a[0, 9] < 1.0


def test_where_it_sits():
    """Fit leaves clear bars round a picture of another shape, fill covers the canvas; scale, place and flip move it;
    tile repeats it."""
    wide = np.ones((10, 40, 3), np.float32)              # 4:1 on a 1:1 canvas
    _, a = vj_layer.prepare(wide, 40, 40, {"pic_fit": "fit", "pic_drift": 0.0})
    assert a[20, 20] > 0.99 and a[2, 20] < 0.01         # bars above and below
    _, a = vj_layer.prepare(wide, 40, 40, {"pic_fit": "fill", "pic_drift": 0.0})
    assert a.min() > 0.99
    _, a = vj_layer.prepare(_disc(), 40, 40, {"pic_scale": 0.5, "pic_x": 0.5, "pic_drift": 0.0})
    assert a[20, 30] > 0.99 and a[20, 10] < 0.01         # half the size, to the right
    _, a = vj_layer.prepare(_disc(), 40, 40, {"pic_scale": 0.5, "pic_y": 0.5, "pic_drift": 0.0})
    assert a[10, 20] > 0.99 and a[30, 20] < 0.01         # up is up
    half = np.zeros((20, 20, 3), np.float32)
    half[:, :10] = 1.0
    rgb, _ = vj_layer.prepare(half, 20, 20, {"pic_flip": "h", "pic_drift": 0.0})
    assert rgb[10, 15, 0] > 0.9 and rgb[10, 4, 0] < 0.1
    _, a = vj_layer.prepare(_disc(), 40, 40, {"pic_fit": "tile", "pic_scale": 0.25, "pic_drift": 0.0})
    assert (a > 0.99).sum() > 4 * (np.pi * (40 * 0.25 * 0.35) ** 2) * 0.8     # many discs
    assert vj_layer.plain({}) and not vj_layer.plain({"pic_scale": 2.0}) and not vj_layer.plain({"pic_key": "dark"})


def test_a_video_s_alpha():
    """A WebM made with alpha (VP9: libvpx keeps it) and a ProRes 4444 are found to have it and read as RGBA - the
    corner clear, the middle not; an MP4 has none."""
    if not (video.ffmpeg() and shutil.which("ffprobe")):
        print("  (no ffmpeg/ffprobe: skipped)")
        return
    d = tempfile.mkdtemp()
    from PIL import Image
    im = Image.new("RGBA", (64, 48), (255, 0, 0, 0))
    im.paste((255, 0, 0, 255), (16, 12, 48, 36))                    # an opaque box on a clear ground
    png = os.path.join(d, "box.png")
    im.save(png)
    made = {}
    for name, args in (("a.webm", ["-c:v", "libvpx-vp9", "-pix_fmt", "yuva420p", "-auto-alt-ref", "0"]),
                       ("a.mov", ["-c:v", "prores_ks", "-profile:v", "4444", "-pix_fmt", "yuva444p10le"]),
                       ("a.mp4", ["-c:v", "libx264", "-pix_fmt", "yuv420p"])):
        p = os.path.join(d, name)
        r = subprocess.run([video.ffmpeg(), "-v", "error", "-y", "-loop", "1", "-i", png, "-t", "1"] + args + [p],
                           capture_output=True)
        made[name] = p if r.returncode == 0 else None
    if made["a.mp4"]:
        assert video.alpha_of(made["a.mp4"]) == ([], False)
    for name in ("a.webm", "a.mov"):
        if not made[name]:
            continue
        dec, has = video.alpha_of(made[name])
        assert has, name
        src_ = video.FfmpegSource(dec + ["-i", made[name]], name, "file", 64, 48, realtime=False, alpha=True)
        import time
        frame = None
        for _ in range(60):
            frame, n = src_.latest()
            if frame is not None:
                break
            time.sleep(0.05)
        src_.close()
        assert frame is not None and frame.shape == (48, 64, 4), (name, None if frame is None else frame.shape)
        assert frame[2, 2, 3] < 30 and frame[24, 32, 3] > 220, (name, frame[2, 2], frame[24, 32])


def test_deck_c_over_the_mix_by_its_alpha():
    """Deck C over the mix: where its alpha is clear the mix shows, where it is not, deck C; its level fades both;
    without an alpha, its black lets the mix through as before."""
    from native import vj

    class App:
        pass
    app = App()
    app.project = type("P", (), {"options": {}, "save": lambda self: None, "path": tempfile.mkdtemp()})()
    o = vj.options(app)
    o["c_mode"] = "over"
    o["fader"] = 0.0
    o["decks"][2]["level"] = 1.0
    base = np.full((2, 2, 3), 100, np.uint8)
    top = np.zeros((2, 2, 3), np.uint8)
    top[0, 0] = (200, 0, 0)
    alpha = np.zeros((2, 2), np.float32)
    alpha[0, 0] = 1.0
    alpha[1, 1] = 1.0                                     # shown, and black: covers the mix
    out = vj.mix(app, base, base, top, alpha)
    assert tuple(out[0, 0]) == (200, 0, 0) and tuple(out[0, 1]) == (100, 100, 100) and tuple(out[1, 1]) == (0, 0, 0)
    out = vj.mix(app, base, base, top)                   # no alpha: black is clear
    assert tuple(out[1, 1]) == (100, 100, 100)


def test_a_shader_channel_s_own_picture():
    """A shader's channel set to image reads the deck's picture for it (a texture a Shadertoy shader asks for), noise
    until one is chosen; a Shadertoy JSON's texture comes in as image, and says so."""
    from native import vj_glsl
    ok, why = vj_glsl.available()
    toy = {"info": {"id": "x", "name": "tex"}, "renderpass": [{"type": "image", "name": "Image", "inputs": [
        {"id": 3, "ctype": "texture", "channel": 0, "src": "/media/a/rock.jpg"}], "outputs": [],
        "code": "void mainImage(out vec4 o, in vec2 u) { o = texture(iChannel0, u / iResolution.xy); }"}]}
    src, _, _ = vj_glsl.from_shadertoy(toy)
    assert vj_glsl.passes(src)[-1][2][0] == "image" and "choose a picture of your own" in src
    if not ok:
        print("  (no OpenGL: the run skipped - " + why + ")")
        return
    from PIL import Image
    pic = os.path.join(tempfile.mkdtemp(), "blue.png")
    Image.new("RGB", (8, 8), (0, 0, 255)).save(pic)
    uni = {"iResolution": (16.0, 12.0, 1.0), "iTime": 0.0}
    for _ in range(2):
        img, err = vj_glsl.render("layer-chan", src, 16, 12, uni, None, None, wait=True,
                                  channels=["image:" + pic, "", "", ""])
    assert not err and img[6, 8, 2] > 0.95 and img[6, 8, 0] < 0.05, (err, None if img is None else img[6, 8])
    for _ in range(2):
        img, err = vj_glsl.render("layer-chan2", src, 16, 12, uni, None, None, wait=True)
    assert not err and img.std() > 0.05                  # noise until a picture is chosen


